#!/usr/bin/env python3
"""Export canonical event-driven zero-shot rows for ms-swift inference."""

from __future__ import annotations

import argparse
import json
from pathlib import Path

from mcp_server.eval.agent_tools.episode.zeroshot_samples import build_event_driven_zeroshot_rows


def main() -> None:
    """Write rows whose tool schemas are generated by ToolSpecRegistry."""

    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--output", required=True, help="Destination JSONL path.")
    args = parser.parse_args()
    output = Path(args.output).expanduser().resolve()
    output.parent.mkdir(parents=True, exist_ok=True)
    with output.open("w", encoding="utf-8") as handle:
        for row in build_event_driven_zeroshot_rows():
            handle.write(json.dumps(row, ensure_ascii=False, separators=(",", ":")) + "\n")
    print(json.dumps({"output": str(output), "rows": 3}, ensure_ascii=False, indent=2))


if __name__ == "__main__":
    main()
